function webLink(value:unknown){try{const u=new URL(String(value||''));return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function mapLinks(d:any){const destination=String(d.mapDestination||d.address||'').trim();const custom=webLink(d.mapsUrl);let maps='';if(custom){const u=new URL(custom);if(u.hostname==='maps.app.goo.gl'||u.hostname==='maps.google.com'||u.hostname==='goo.gl'&&u.pathname.startsWith('/maps')||['google.com','www.google.com'].includes(u.hostname)&&u.pathname.startsWith('/maps'))maps=custom;}return {destination,maps:maps||(destination?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(destination):''),directions:destination?'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(destination):''};}
