function startCrop(source:File|string,target:'avatar'|'cover'){if(busy)return;if(typeof source!=='string'&&(!['image/jpeg','image/png','image/webp'].includes(source.type)||source.size>MAX_SOURCE_PHOTO_BYTES)){setMsg(t('JPG, PNG ou WebP : maximum 40 Mo.','JPG، PNG ولا WebP: حتى 40 Mo.'));return;}setCrop({source,target});}
