const t=(fr:string,da:string)=>ar?da:fr;
async function checkSession(){const epoch=++authEpoch.current;try{const r=await fetch('/api/auth',{cache:'no-store'});if(!r.ok)throw new Error();const b=await r.json() as {authenticated?:boolean,email?:unknown};if(epoch!==authEpoch.current)return;setAuth(b.authenticated===true);setAccountEmail(b.authenticated===true&&typeof b.email==='string'?b.email:'');setSessionChecked(true);}catch{if(epoch===authEpoch.current)setSessionChecked(true);}}
async function logout(){authEpoch.current++;setBusy(true);try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});if(!r.ok)throw new Error();setAuth(false);setAccountEmail('');setSessionChecked(true);location.assign('/');}catch{setMsg(t('Déconnexion impossible. Réessayez.','ما تخرجش الحساب. عاود حاول.'));}finally{setBusy(false);}}
useEffect(()=>{if(view==='app')return;void checkSession();const refresh=()=>{if(document.visibilityState==='visible')void checkSession()};document.addEventListener('visibilitychange',refresh);return()=>{authEpoch.current++;document.removeEventListener('visibilitychange',refresh)};},[view]);
async function loadStorage(){try{const r=await fetch('/api/upload?stats=1');if(r.ok)setStorage(await r.json());}catch{}}
useEffect(()=>{if(auth&&tab==='media')void loadStorage();},[auth,tab]);
async function checkContactCard(){setCardCheck('loading');setMyContactCard(null);try{const r=await fetch('/api/data?exchange=1');const b:any=await r.json();if(r.status===401){setCardCheck('login');return;}if(!r.ok)throw new Error();if(b.card&&b.card.id!==id){setMyContactCard(b.card);setCardCheck('ready');}else setCardCheck('none');}catch{setCardCheck('error');}}
useEffect(()=>{if(modal==='contact'){setUseMyCard(false);void checkContactCard();}},[modal,id]);
useEffect(()=>{if(new URLSearchParams(location.search).get('lang')==='ar')setAr(true)},[]);
