async function load(authMode='login'){authEpoch.current++;setBusy(true);setAuthLoading(true);setAuthLoadError(false);try{const r=await fetch('/api/data');const b:any=await r.json();if(r.status===401){setAuth(false);setAccountEmail('');setSessionChecked(true);location.assign('/auth?mode='+authMode+(ar?'&lang=ar':''));return;}else if(!r.ok){setAuthLoadError(true);setMsg(b.error);}else{setAuth(true);setAccountEmail(typeof b.email==='string'?b.email:(b.profile?.email||''));setSessionChecked(true);setCanAdmin(!!b.admin);setSubscription(b.profile);if(b.profile){setData({...blank,...JSON.parse(b.profile.data),promotions:normalizePromotions(JSON.parse(b.profile.data).promotions),services:normalizeCatalogue(JSON.parse(b.profile.data).services)});setId(b.profile.id);setPublished(!!b.profile.published);}setInbox(b.requests);setContacts(b.contacts||[]);setNotifications(b.notifications||[]);setMailConfigured(!!b.mailConfigured);setOrders(b.orders);setMsg('');}}catch{setAuthLoadError(true);setMsg(t('Service indisponible. Réessayez.','الخدمة ما متوفراش. عاود جرّب.'))}setBusy(false);setAuthLoading(false);setLoaded(true)}
async function action(body:any){setBusy(true);try{const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const b:any=await r.json();if(!r.ok)throw new Error(b.error);return b;}finally{setBusy(false)}}
async function save(){try{const b=await action({action:'save',data,published});setId(b.id);setMsg(b.cleanupPending?t('Carte enregistrée. Le nettoyage du stockage sera réessayé à votre prochaine action.','تسجلات الكارط. تنظيف التخزين غادي يتعاود فالإجراء الجاي.'):t('Votre carte est enregistrée.','تسجلات الكارط ديالك.'));void loadStorage();}catch(e:any){setMsg(e.message)}}
async function upload(f:File,field:string){if(uploadLock.current)return false;uploadLock.current=true;setBusy(true);try{const form=new FormData();form.append('file',await compressPhoto(f));const r=await fetch('/api/upload',{method:'POST',body:form});const b:any=await r.json();if(!r.ok)throw new Error(b.error);if(b.storage)setStorage(b.storage);setData((d:any)=>({...d,[field]:field==='photos'?[...d.photos,b.url].slice(0,10):b.url}));setMsg(t('Fichier ajouté. Enregistrez votre carte.','تزّاد الملف. سجّل الكارط ديالك.'));return true;}catch(e:any){setMsg(e.message);return false;}finally{setBusy(false);uploadLock.current=false}}
async function uploadVideo(file:File){if(uploadLock.current)return;const error=mediaError(file.type,file.size);if(!VIDEO_TYPES.includes(file.type)||error){setMsg(error||t('Choisissez une vidéo MP4, WebM ou MOV.','اختار فيديو MP4، WebM ولا MOV.'));return;}uploadLock.current=true;setBusy(true);try{const form=new FormData();form.append('file',await compressPhoto(file));const r=await fetch('/api/upload',{method:'POST',body:form});const b:any=await r.json();if(!r.ok)throw new Error(b.error||'Importation impossible');if(b.storage)setStorage(b.storage);setData((d:any)=>({...d,recordedVideo:b.url}));setMsg(t('Vidéo ajoutée. Enregistrez votre carte pour la publier.','تزّاد الفيديو. سجّل الكارط ديالك باش تنشرو.'));}catch(e:any){setMsg(e.message);}finally{uploadLock.current=false;setBusy(false);}}
async function uploadPhotos(files:File[]){if(uploadLock.current||!files.length)return;const remaining=Math.max(0,10-data.photos.length);if(!remaining){setMsg(t('La galerie contient déjà 10 photos.','الگالوري فيها 10 تصاور دابا.'));return;}uploadLock.current=true;setBusy(true);const errors:string[]=[];const valid=files.filter(f=>{if(!['image/jpeg','image/png','image/webp'].includes(f.type)){errors.push(f.name+': '+t('format non accepté','نوع ما مقبولش'));return false;}if(f.size>MAX_SOURCE_PHOTO_BYTES){errors.push(f.name+': '+t('plus de 40 Mo avant compression','أكثر من 40 Mo قبل الضغط'));return false;}return true;});const chosen=valid.slice(0,remaining);const excess=Math.max(0,valid.length-remaining);let added=0;setUploadProgress({done:0,total:chosen.length});try{for(let i=0;i<chosen.length;i++){const f=chosen[i];try{const form=new FormData();form.append('file',await compressPhoto(f));const r=await fetch('/api/upload',{method:'POST',body:form});const b:any=await r.json();if(!r.ok)throw new Error(b.error||'Échec');if(b.storage)setStorage(b.storage);setData((d:any)=>({...d,photos:[...d.photos,b.url].slice(0,10)}));added++;}catch(e:any){errors.push(f.name+': '+e.message);}setUploadProgress({done:i+1,total:chosen.length});}let message=added?t(added+' photo(s) ajoutée(s). Enregistrez votre carte.', 'تزادو '+added+' تصاور. سجّل الكارط ديالك.'):t('Aucune photo ajoutée.','ما تزادت حتى تصويرة.');if(excess)message+=' '+t(excess+' photo(s) non importée(s) : limite de 10 photos.',excess+' تصاور ما تزادوش: الحد هو 10 تصاور.');if(errors.length)message+=' '+errors.join(' · ');setMsg(message);}finally{setUploadProgress(null);setBusy(false);uploadLock.current=false;}}
useEffect(()=>{if(modal!=='rdv'||!id)return;const controller=new AbortController();setSlotsBusy(true);setSlots([]);fetch('/api/availability?id='+id+'&date='+date+'&service='+serviceIndex,{signal:controller.signal}).then(async r=>{const b:any=await r.json();if(!r.ok)throw new Error(b.error);setSlots(b.slots)}).catch(e=>{if(e.name!=='AbortError')setMsg(e.message)}).finally(()=>{if(!controller.signal.aborted)setSlotsBusy(false)});return ()=>controller.abort()},[modal,id,date,serviceIndex]);
function updateCatalogue(itemId:string,key:string,value:any){setData((d:any)=>({...d,services:d.services.map((item:any)=>item.id===itemId?{...item,[key]:value}:item)}));}
async function uploadCatalogue(file:File,itemId:string){if(uploadLock.current)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>MAX_SOURCE_PHOTO_BYTES){setMsg(t('JPG, PNG ou WebP, maximum 40 Mo avant compression.','JPG، PNG ولا WebP، حتى 40 Mo قبل الضغط.'));return;}uploadLock.current=true;setBusy(true);try{const form=new FormData();form.append('file',await compressPhoto(file));const r=await fetch('/api/upload',{method:'POST',body:form});const b:any=await r.json();if(!r.ok)throw new Error(b.error||'Importation impossible');if(b.storage)setStorage(b.storage);updateCatalogue(itemId,'image',b.url);setMsg(t('Photo ajoutée. Enregistrez votre catalogue.','تزادت التصويرة. سجّل الكاتالوگ ديالك.'));}catch(e:any){setMsg(e.message)}finally{setBusy(false);uploadLock.current=false}}
function updatePromotion(promoId:string,key:string,value:any){setData((d:any)=>({...d,promotions:(d.promotions||[]).map((p:any)=>p.id===promoId?{...p,[key]:value}:p)}));}
async function uploadPromotion(file:File,promoId:string){if(uploadLock.current)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>MAX_SOURCE_PHOTO_BYTES){setMsg(t('JPG, PNG ou WebP, maximum 40 Mo avant compression.','JPG، PNG ولا WebP، حتى 40 Mo قبل الضغط.'));return;}uploadLock.current=true;setBusy(true);try{const form=new FormData();form.append('file',await compressPhoto(file));const r=await fetch('/api/upload',{method:'POST',body:form});const b:any=await r.json();if(!r.ok)throw new Error(b.error||'Importation impossible');if(b.storage)setStorage(b.storage);updatePromotion(promoId,'image',b.url);setMsg(t('Photo ajoutée. Enregistrez votre carte.','تزادت التصويرة. سجّل الكارط ديالك.'));}catch(e:any){setMsg(e.message)}finally{setBusy(false);uploadLock.current=false}}
